import { LitElement, html, css, svg, nothing } from 'lit';
import { customElement, state } from 'lit/decorators.js';
import '../components/sw-page';
import '../components/sw-kpi';
import '../components/sw-card';
import '../components/sw-badge';
import '../components/sw-button';
import '../components/sw-icon';
import '../components/sw-state-panel';
import '../components/sw-scene';
import '../components/sw-camera-tile';
import { demoEvents, demoHealth, demoScene, demoSites, demoWall, eventTypeLabel } from '../fixtures/catalog';
import { navigate } from '../router';
import { cap, isApi, session, webrtcServer } from '../api/session';
import { WEBRTC_REQUIRED_SHORT, WEBRTC_REQUIRED_TEXT, WEBRTC_SETTINGS_HREF, isStandaloneRow } from '../api/camera-visibility';
import { ApiError, get } from '../api/client';
import { listCameras } from '../api/maps';
import { eventsSummary, listEvents, thumbnailUrl, EVENT_LABEL, EVENT_TONE as API_EVENT_TONE, type EventsSummary, type VmsEvent } from '../api/events';
import { bidi } from '../i18n/bidi';
import { getStorage, fmtMb, type StorageReport } from '../api/storage';
import { healthSummary, STATUS_LABEL, type HealthSummary } from '../api/health';
import { productSettings } from '../api/prefs';
import { snapshotUrl } from '../api/media';
import type { Camera, Site } from '../api/types';
import { TileLayoutController } from '../api/tile-layout';
import { dateInZone } from '../api/recordings';
import { liveTileKnobs } from '../styles/tile-knobs';
import { SkinController } from '../design/skin';
import { bubbleChrome } from '../styles/bubble-chrome';
import { syncErrorText } from '../api/ha-sync-status';
import { attentionFit } from './live-overview-logic';
import { timeText } from '../api/day-format';

/** GET /api/v1/health — connection facts used for the attention list. */
interface RawHealth {
  events: { ingest: { connected: boolean; last_event_at: string | null; events_stored: number } };
  home_assistant: { configured: boolean; connected: boolean; last_error: string | null };
  discovery: { cameras_last_error: string | null };
}

interface Spot {
  kind: 'critical' | 'alert' | 'info';
  title: string;
  meta: string;
  why: string;
  link: string;
}

function greeting(hour: number): string {
  if (hour < 5) return 'לילה טוב';
  if (hour < 12) return 'בוקר טוב';
  if (hour < 17) return 'צהריים טובים';
  if (hour < 21) return 'ערב טוב';
  return 'לילה טוב';
}

const EVENT_TONE: Record<string, string> = { person: 'var(--sw-tl-person)', vehicle: 'var(--sw-tl-vehicle)', motion: 'var(--sw-tl-motion)', line: 'var(--sw-tl-line)', offline: 'var(--sw-tl-offline)', door: 'var(--sw-tl-door)' };
const EVENT_SCENE: Record<string, string> = { 'כניסה ראשית': 'entrance', 'חצר אחורית': 'backyard', מחסן: 'warehouse', לובי: 'lobby', 'חניה מקורה': 'parking' };

/**
 * SC01 — overview dashboard (board 1 screen 1 / board 2 screen 15 on phones): greeting, four stat
 * cards, storage donut beside site health, and recent events with thumbnails. Attention items say why
 * they are shown (deterministic rules, no scoring).
 */
@customElement('live-overview')
export class LiveOverview extends LitElement {
  /** 0.1.157: the bubble skin's chrome keys on the host's data-skin (styles/bubble-chrome.ts). */
  readonly bubbleSkin = new SkinController(this);
  @state() private cams: Camera[] | null = null;
  @state() private recorder: { name: string; model: string | null } | null = null;
  @state() private sites: Site[] | null = null;
  @state() private summary: EventsSummary | null = null;
  @state() private summaryDenied = false; // events.read missing: the KPI says so instead of a misleading 0 (0.1.80)
  @state() private recent: VmsEvent[] = [];
  @state() private storage: StorageReport | null = null;
  @state() private health: HealthSummary | null = null;
  @state() private raw: RawHealth | null = null;
  @state() private tz = 'Asia/Jerusalem';
  @state() private now = new Date();
  @state() private loaded = false;
  /** WARMUP-POLISH-2421 (owner rule: a control screen never scrolls): how many attention items fit the card on a desktop (null: all
   * of them, or not measured yet) and the page of them shown; the card pages instead of scrolling inside. */
  @state() private spotFit: number | null = null;
  @state() private spotPage = 0;
  private spotMeasure = true;
  private spotObserver: ResizeObserver | null = null;
  private spotCount = -1;
  /** UXREST-295: every call of the first read failed (server away): an error with a retry, not zeros and "reading the system state" for ever. */
  @state() private loadFailed = false;
  private timer = 0;
  private clockTimer = 0;
  /** Owner 2026-09-29: the tiles' shape (ui.tile_layout) - compact rectangles on a phone by default. */
  private tiles = new TileLayoutController(this);

  connectedCallback() {
    super.connectedCallback();
    if (!isApi()) return;
    void this.load();
    this.timer = window.setInterval(() => void this.load(), 60_000);
    this.clockTimer = window.setInterval(() => (this.now = new Date()), 30_000);
  }

  disconnectedCallback() {
    this.spotObserver?.disconnect();
    this.spotObserver = null;
    window.clearInterval(this.timer);
    window.clearInterval(this.clockTimer);
    super.disconnectedCallback();
  }

  private async load() {
    // the storage report can take tens of seconds when its cache is cold: never let it hold the rest back
    void this.loadStorage();
    const [settings, cams, sites, summary, recent, health, raw] = await Promise.allSettled([
      productSettings(),
      listCameras(),
      get<{ sites: Site[] }>('sites?tree=true'),
      eventsSummary(),
      listEvents({ limit: 6 }),
      healthSummary(),
      get<RawHealth>('health'),
    ]);
    if (settings.status === 'fulfilled') this.tz = settings.value['time.zone'] ?? this.tz;
    if (cams.status === 'fulfilled') {
      this.cams = cams.value.cameras.filter((c) => c.enabled && c.recorder_enabled !== false); // CR-024: not counted, not shown while its recorder is disabled
      this.recorder = cams.value.recorder;
    } else if (this.cams === null) this.cams = [];
    if (sites.status === 'fulfilled') this.sites = sites.value.sites;
    else if (this.sites === null) this.sites = [];
    if (summary.status === 'fulfilled') this.summary = summary.value;
    else this.summaryDenied = summary.reason instanceof ApiError && summary.reason.status === 403;
    if (recent.status === 'fulfilled') this.recent = recent.value.events;
    if (health.status === 'fulfilled') this.health = health.value;
    if (raw.status === 'fulfilled') this.raw = raw.value;
    this.loadFailed = [cams, sites, health, raw].every((r) => r.status === 'rejected') && this.cams?.length === 0 && this.health === null;
    this.loaded = true;
    this.now = new Date();
  }

  private async loadStorage() {
    try {
      this.storage = await getStorage(); // 403 for non-admins: the card is simply absent
    } catch {
      this.storage = null;
    }
  }

  private fmtTime(iso: string): string {
    return timeText(new Date(iso), { timeZone: this.tz });
  }

  private spots(): Spot[] {
    const out: Spot[] = [];
    const cams = this.cams ?? [];
    for (const c of cams.filter((x) => x.status === 'offline')) {
      const seen = c.last_seen_at ? ` · נראתה לאחרונה ${this.fmtTime(c.last_seen_at)}` : '';
      // NVRLESS-CAMERAS-2411: a camera without a recorder has no channel and no recorder that reports it
      if (isStandaloneRow(c)) out.push({ kind: 'critical', title: `מצלמה מנותקת: ${c.name}`, meta: `מצלמה ללא מקליט${seen}`, why: 'מוצג כי המצלמה אינה עונה בכתובת הווידאו שלה', link: `#/live/cameras/${c.id}` });
      else out.push({ kind: 'critical', title: `מצלמה מנותקת: ${c.name}`, meta: `ערוץ ${c.channel}${seen}`, why: 'מוצג כי ה־NVR מדווח שהערוץ אינו מחובר', link: `#/live/cameras/${c.id}` });
    }
    for (const it of (this.health?.items ?? []).filter((i) => i.status !== 'ok')) {
      out.push({ kind: it.status === 'error' ? 'critical' : 'alert', title: it.label, meta: `בדיקת מערכת · ${STATUS_LABEL[it.status]}`, why: 'מוצג כי בדיקת הבריאות של ה־Add-on מדווחת על כך', link: '#/system/diagnostics' });
    }
    const un = this.summary?.today.unacked ?? 0;
    if (un > 0) {
      const by = Object.entries(this.summary?.today.by_type ?? {}).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([t, n]) => `${EVENT_LABEL[t as keyof typeof EVENT_LABEL] ?? t} ${n}`).join(' · ');
      out.push({ kind: 'alert', title: `${un} אירועים שלא נבדקו היום`, meta: by, why: 'מוצג כי אירועים ממתינים לסימון טיפול במרכז האירועים', link: '#/investigate/events' });
    }
    const ing = this.raw?.events.ingest;
    if (ing?.connected && !ing.events_stored && !ing.last_event_at) {
      out.push({ kind: 'info', title: 'ה־NVR לא שלח התראות מאז ההפעלה', meta: 'אירועי תנועה נגזרים מההקלטות כל 10 דקות', why: 'מוצג כי זרם ההתראות מחובר אך ריק — ב־NVR יש להפעיל "Notify Surveillance Center" ב־linkage של זיהוי התנועה', link: '#/system/setup' });
    }
    if (this.raw?.home_assistant.configured && !this.raw.home_assistant.connected) {
      out.push({ kind: 'alert', title: 'אין חיבור לתשתית המערכת', meta: syncErrorText(this.raw.home_assistant.last_error), why: 'מוצג כי מצבי הישויות והדלתות עלולים להיות מיושנים', link: '#/system/setup' });
    }
    return out;
  }

  private renderApi() {
    const me = session.me?.user;
    const name = me?.display_name || me?.username || '';
    const hour = Number(this.now.toLocaleString('en-GB', { hour: 'numeric', hour12: false, timeZone: this.tz }));
    const cams = this.cams ?? [];
    const online = cams.filter((c) => c.status === 'online').length;
    const sites = this.sites ?? [];
    const floors = sites.flatMap((s) => (s.buildings ?? []).flatMap((b) => b.floors ?? []));
    const h = this.health;
    const tone = !h ? 'neutral' : h.status === 'ok' ? 'live' : h.status === 'warn' ? 'stale' : 'offline';
    const firstIssue = h?.items.find((i) => i.status !== 'ok');
    const spots = this.loaded ? this.spots() : [];
    const st = this.storage;
    const tot = st?.totals ?? null;
    const usedPct = tot?.used_pct ?? null;
    const r = 34;
    const c = 2 * Math.PI * r;
    const favorites = cams.filter((x) => x.status === 'online').slice(0, 2);
    const layout = this.tiles.layout;
    if (this.loaded && this.loadFailed) {
      return html`<sw-page heading=${`${greeting(hour)}${name ? `, ${name}` : ''}`}><sw-state-panel state="error" actionLabel="נסו שוב" @action=${() => void this.load()}></sw-state-panel></sw-page>`;
    }
    return html`
      <sw-page heading=${`${greeting(hour)}${name ? `, ${name}` : ''}`} subheading=${h ? `מצב המערכת: ${STATUS_LABEL[h.status]}${firstIssue ? ` · ${firstIssue.label}` : ' · כל הבדיקות תקינות'}` : 'קורא את מצב המערכת…'}>
        <div slot="actions" class="date">${this.now.toLocaleDateString('he-IL', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: this.tz })}<br />${timeText(this.now, { timeZone: this.tz })}</div>
        <div class="kpis" data-overview-kpis>
          <sw-kpi data-overview-tile="cameras" icon="camera" tone=${cams.length && online === cams.length ? 'live' : online ? 'stale' : 'offline'} value=${`${online}/${cams.length}`} label="מצלמות" detail=${!webrtcServer() ? WEBRTC_REQUIRED_SHORT : this.recorder ? `מחוברות · ${this.recorder.model ?? this.recorder.name}` : 'מחוברות'} layout=${layout} href=${!webrtcServer() ? WEBRTC_SETTINGS_HREF : cap('nvr') ? '#/system/devices?sort=offline' : '#/live/wall'} hint=${webrtcServer() ? 'פתח את רשימת המצלמות' : WEBRTC_REQUIRED_TEXT} ?data-webrtc-required=${!webrtcServer()}></sw-kpi>
          <sw-kpi data-overview-tile="sites" icon="building" value=${String(sites.length)} label="אתרים" detail=${`${floors.length} קומות · ${floors.filter((f) => f.has_plan).length} עם תוכנית`} tone="neutral" layout=${layout} href="#/explore/sites" hint="פתח את האתרים"></sw-kpi>
          <sw-kpi data-overview-tile="events" icon="bell" value=${this.summaryDenied ? '—' : String(this.summary?.today.total ?? 0)} label="אירועים" detail=${this.summaryDenied ? 'ללא הרשאה לאירועים' : 'היום'} tone="neutral" badge=${this.summary?.today.unacked ? `${this.summary.today.unacked} לבדיקה` : ''} layout=${layout} href=${`#/investigate/events?date=${dateInZone(this.now, this.tz)}`} hint="פתח את אירועי היום"></sw-kpi>
          <sw-kpi data-overview-tile="health" icon="shield" tone=${tone} value=${h ? STATUS_LABEL[h.status] : '…'} label="מצב מערכת" detail=${firstIssue ? firstIssue.label : 'NVR, go2rtc, תשתית המערכת ואחסון'} layout=${layout} href="#/system/diagnostics?tab=health" hint="פתח את פרטי הבריאות"></sw-kpi>
        </div>
        ${favorites.length
          ? html`<div class="fav" data-overview-favorites>
              ${favorites.map((cam) => html`<sw-camera-tile name=${cam.name} state="live" cameraId=${cam.id} poster=${snapshotUrl(cam.id)} .stillRefresh=${cam.live_kind === 'still' ? cam.still_refresh_s ?? 10 : 0} noDemo @click=${() => navigate(`/live/cameras/${cam.id}`)}></sw-camera-tile>`)}
            </div>`
          : nothing}
        <div class="row2">
          ${st && tot && cap('nvr') /* NVRLESS-CAMERAS-2411: the recorder's storage card stays a recorder card */
            ? html`<sw-card heading="אחסון" subheading=${st.cached ? 'מהמטמון · נמדד מול ה־NVR' : 'נמדד מול ה־NVR'}>
                <div class="donut">
                  <svg viewBox="0 0 84 84" role="img" aria-label=${`אחסון בשימוש ${usedPct ?? 0}%`}>
                    ${svg`<circle cx="42" cy="42" r=${r} fill="none" stroke="var(--sw-surface-3)" stroke-width="9" />
                    <circle cx="42" cy="42" r=${r} fill="none" stroke="var(--sw-accent)" stroke-width="9" stroke-linecap="round" stroke-dasharray=${`${(c * (usedPct ?? 0)) / 100} ${c}`} transform="rotate(-90 42 42)" />
                    <text x="42" y="47" text-anchor="middle" font-size="15" font-weight="700" fill="var(--sw-text)" font-family="var(--sw-font)">${usedPct ?? 0}%</text>`}
                  </svg>
                  <div class="txt">
                    <div class="big">${fmtMb(tot.used_mb)} מתוך ${fmtMb(tot.capacity_mb)}</div>
                    <div class="bar"><i style=${`inline-size:${usedPct ?? 0}%`}></i></div>
                    <div class="muted">${st.retention.measured_days_min !== null ? `הקלטה ישנה ביותר ≈ ${st.retention.measured_days_min}${st.retention.measured_days_max !== null && st.retention.measured_days_max !== st.retention.measured_days_min ? `–${st.retention.measured_days_max}` : ''} ימים (נמדד)` : st.retention.measured_reason}${st.work_mode ? ` · ${st.work_mode}` : ''} · ${tot.disks} דיסקים</div>
                  </div>
                </div>
              </sw-card>`
            : nothing}
          <sw-card heading="אתרים ומבנים" subheading=${sites.length ? `${sites.length} אתרים · ${floors.length} קומות` : 'עדיין לא הוגדרו אתרים'}>
            <div class="hgrid">${sites.map((s) => {
              const fl = (s.buildings ?? []).flatMap((b) => b.floors ?? []);
              const plans = fl.filter((f) => f.has_plan).length;
              const placed = fl.reduce((n, f) => n + f.camera_count, 0);
              return html`<div class="hrow link" role="link" tabindex="0" @click=${() => navigate('/explore/sites')} @keydown=${(k: KeyboardEvent) => { if (k.key === 'Enter' || k.key === ' ') { k.preventDefault(); navigate('/explore/sites'); } }}><span>${s.name}<div class="muted">${(s.buildings ?? []).length} מבנים · ${fl.length} קומות · ${placed} מצלמות מוצבות · ${plans}/${fl.length} תוכניות</div></span><span class="status"><i style=${`--c:${fl.length && plans === fl.length ? 'var(--sw-live)' : 'var(--sw-stale)'}`}></i>${fl.length && plans === fl.length ? 'תוכניות מפורסמות' : 'חסרות תוכניות'}</span></div>`;
            })}
            ${this.recorder ? html`<div class="hrow"><span>NVR · ${this.recorder.name}<div class="muted">${this.recorder.model ?? ''} · ${online}/${cams.length} מצלמות מחוברות</div></span><span class="status"><i style=${`--c:${online === cams.length ? 'var(--sw-live)' : 'var(--sw-offline)'}`}></i>${online === cams.length ? 'מחובר' : `${cams.length - online} מנותקות`}</span></div>` : nothing}</div>
          </sw-card>
        </div>
        <div class="row3">
          <sw-card fill heading="אירועים אחרונים" subheading=${this.summary ? `${this.summary.today.total} היום · ${this.summary.today.measured} נמדדו · ${this.summary.today.inferred} נגזרו מהקלטה` : ''}>
            <a slot="actions" class="seeall" href="#/investigate/events">הצג הכל</a>
            ${this.recent.length
              ? this.recent.map(
                  (e) => html`<div class="ev" data-overview-event role="link" tabindex="0" @click=${() => navigate(`/investigate/events/${e.id}`)} @keydown=${(k: KeyboardEvent) => { if (k.key === 'Enter' || k.key === ' ') { k.preventDefault(); navigate(`/investigate/events/${e.id}`); } }}>
                    ${e.thumbnail === 'ready'
                      ? html`<img class="thumb" src=${thumbnailUrl(e.id)} alt="" loading="lazy" />`
                      : html`<div class="none"><sw-icon name=${e.type === 'offline' || e.type === 'coverage_gap' ? 'offline' : e.type === 'door' || e.type === 'io' ? 'door' : e.type === 'person' ? 'user' : e.type === 'vehicle' ? 'route' : 'bell'} size=${14}></sw-icon></div>`}
                    <div class="txt"><b style=${`--tone:${API_EVENT_TONE[e.type as keyof typeof API_EVENT_TONE] ?? 'var(--sw-tl-offline)'}`}><i></i>${EVENT_LABEL[e.type as keyof typeof EVENT_LABEL] ?? e.type}${e.acked_at ? '' : ' · לבדיקה'}</b><small>${e.camera_name ?? (e.details as { name?: string } | undefined)?.name ?? 'ללא מצלמה'} · ${e.confidence === 'inferred' ? 'נגזר מהקלטה' : e.source === 'ha' ? 'חיישן התקן' : 'התראה'}</small></div>
                    <time>${this.fmtTime(e.occurred_at)}</time>
                  </div>`,
                )
              : html`<div class="muted">${this.loaded ? 'אין אירועים ב־24 השעות האחרונות' : 'טוען…'}</div>`}
          </sw-card>
          ${this.renderAttention(spots, html`<div class="muted" data-overview-calm>${this.loaded ? 'הכול תקין — אין פריטים שדורשים תשומת לב כרגע.' : 'בודק…'}</div>`)}
        </div>
      </sw-page>
    `;
  }

  static styles = [bubbleChrome, liveTileKnobs, css`
    .date {
      font-size: var(--sw-fs-xs);
      color: var(--sw-text-3);
      text-align: end;
      line-height: 1.3;
    }
    .kpis {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 12px;
    }
    .row2 {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 1.4fr);
      gap: 12px;
      align-items: stretch;
    }
    .row3 {
      display: grid;
      grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
      gap: 12px;
      align-items: start;
    }
    .donut {
      display: flex;
      align-items: center;
      gap: 14px;
    }
    .donut svg {
      inline-size: 84px;
      block-size: 84px;
      flex-shrink: 0;
    }
    .donut .txt {
      flex: 1;
      min-inline-size: 0;
    }
    .donut .big {
      font-size: var(--sw-fs-sm);
      font-weight: var(--sw-fw-semibold);
    }
    .bar {
      block-size: 6px;
      border-radius: var(--sw-r-pill);
      background: var(--sw-surface-3);
      overflow: hidden;
      margin-block: 6px 4px;
    }
    .bar i {
      display: block;
      block-size: 100%;
      inline-size: 68%;
      background: var(--sw-accent);
    }
    .muted {
      color: var(--sw-text-3);
      font-size: var(--sw-fs-xs);
    }
    .hrow {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 10px;
      padding: 7px 0;
      border-block-end: 1px solid var(--sw-border);
      font-size: var(--sw-fs-sm);
    }
    .hrow:last-child {
      border-block-end: 0;
    }
    .hrow.link {
      cursor: pointer;
      border-radius: var(--sw-r-xs);
      transition: background var(--sw-t-fast) var(--sw-ease);
    }
    /* POLISH4-WP2: the wash follows a hovering fine pointer only (it stuck on a tapped row on touch) */
    @media (hover: hover) and (pointer: fine) {
      .hrow.link:hover,
      .ev:hover {
        background: var(--sw-hover-wash);
      }
    }
    .hrow.link:focus-visible,
    .ev:focus-visible {
      outline: var(--sw-focus-w) solid var(--sw-focus);
      outline-offset: -2px;
      border-radius: var(--sw-r-xs);
    }
    .status {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: var(--sw-fs-xs);
      color: var(--sw-text-2);
    }
    .status i {
      inline-size: 7px;
      block-size: 7px;
      border-radius: 50%;
      background: var(--c);
    }
    .ev {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 7px 4px;
      margin-inline: -4px;
      border-block-end: 1px solid var(--sw-border);
      font-size: var(--sw-fs-sm);
      cursor: pointer;
      border-radius: var(--sw-r-xs);
      transition: background var(--sw-t-fast) var(--sw-ease);
    }
    .ev:last-child {
      border-block-end: 0;
    }
    .ev sw-scene,
    .ev img.thumb,
    .ev .none {
      inline-size: 56px;
      block-size: 36px;
      border-radius: var(--sw-r-xs);
      flex-shrink: 0;
      overflow: hidden;
    }
    .ev img.thumb {
      object-fit: cover;
      display: block;
      background: var(--sw-surface-3);
    }
    .spot.info .ic {
      color: var(--sw-accent);
      background: var(--sw-accent-soft);
    }
    .ev .none {
      background: var(--sw-surface-3);
      display: grid;
      place-items: center;
      color: var(--sw-text-3);
    }
    .ev .txt {
      flex: 1;
      min-inline-size: 0;
    }
    .ev .txt b {
      display: flex;
      align-items: center;
      gap: 6px;
      font-weight: var(--sw-fw-semibold);
      font-size: var(--sw-fs-sm);
    }
    .ev .txt b i {
      inline-size: 7px;
      block-size: 7px;
      border-radius: 50%;
      background: var(--tone);
      flex-shrink: 0;
    }
    .ev .txt small {
      color: var(--sw-text-3);
      font-size: var(--sw-fs-xs);
      display: block;
    }
    .ev time {
      font-size: var(--sw-fs-xs);
      color: var(--sw-text-3);
      white-space: nowrap;
    }
    .spot {
      display: flex;
      gap: 10px;
      padding: 8px 0;
      border-block-end: 1px solid var(--sw-border);
      align-items: flex-start;
      font-size: var(--sw-fs-sm);
    }
    .spot:last-child {
      border-block-end: 0;
    }
    .spot .ic {
      display: grid;
      place-items: center;
      inline-size: 30px;
      block-size: 30px;
      border-radius: var(--sw-r-sm);
      background: var(--sw-stale-soft);
      color: var(--sw-stale);
      flex-shrink: 0;
    }
    .spot.critical .ic {
      background: var(--sw-danger-soft);
      color: var(--sw-danger);
    }
    .spot.critical .t {
      color: var(--sw-danger-text);
    }
    .spot .t {
      font-weight: var(--sw-fw-semibold);
    }
    .spot .actions a {
      text-decoration: none;
    }
    .spot .why {
      font-size: var(--sw-fs-xs);
      color: var(--sw-text-3);
    }
    .spot .actions {
      margin-inline-start: auto;
      align-self: center;
    }
    .spot .sbody {
      min-inline-size: 0;
      flex: 1 1 auto;
    }
    /* WARMUP-POLISH-2421: the attention pager (a desktop card pages its items instead of scrolling) */
    .spotpager {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 10px;
      block-size: 30px;
      margin-block-start: 4px;
      font-size: var(--sw-fs-xs);
      color: var(--sw-text-2);
      font-variant-numeric: tabular-nums;
    }
    .spotpager button {
      display: grid;
      place-items: center;
      inline-size: 28px;
      block-size: 28px;
      border: 1px solid var(--sw-border);
      border-radius: var(--sw-r-sm);
      background: var(--sw-surface);
      color: var(--sw-text);
      cursor: pointer;
      padding: 0;
    }
    .spotpager button:disabled {
      opacity: 0.4;
      cursor: default;
    }
    @media (min-width: 1024px) {
      /* one line each for the meta and the reason on a desktop (the full text is the tooltip): more items fit before the pager */
      .spot .sbody > .muted,
      .spot .sbody > .why {
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
      }
    }
    .seeall {
      color: var(--sw-accent-text);
      text-decoration: none;
      font-size: var(--sw-fs-xs);
      font-weight: var(--sw-fw-medium);
    }
    .fav {
      display: none;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 10px;
    }
    @media (max-width: 1023px) {
      .row2,
      .row3 {
        grid-template-columns: 1fr;
      }
    }
    /* NOSCROLL-297 (owner rule: a control screen fits the viewport on a desktop): the page takes the screen's height and the last
       row - the recent events and the attention list, the two naturally long lists - takes what is left; each list scrolls inside
       its own card (sw-card fill). Below 200 px of room the row keeps that height and the page scrolls as before (a very short window). */
    @media (min-width: 1024px) {
      sw-page {
        block-size: 100%;
      }
      .row3 {
        flex: 0 1 auto;
        min-block-size: 200px;
        grid-template-rows: minmax(0, 1fr);
      }
      .row3 > sw-card {
        max-block-size: 100%;
      }
    }
    @media (max-width: 767px) {
      .kpis {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 8px;
      }
      .fav {
        display: grid;
      }
      .date {
        display: none;
      }
    }
    /* owner 2026-09-29: compact tiles (ui.tile_layout) - rectangles, icon beside the value; the sizes are the
       --lv-tile-* knobs (styles/tile-knobs.ts). Four across on a desktop, the knob's column count on a phone. */
    :host([data-tile-layout='compact']) .kpis {
      grid-template-columns: repeat(auto-fit, minmax(var(--lv-tile-compact-col-min), 1fr));
      grid-auto-rows: 1fr;
      gap: var(--lv-tile-compact-grid-gap);
      padding-block-start: 6px; /* room for a badge riding the tile's top corner */
    }
    @media (min-width: 1024px) {
      :host([data-tile-layout='compact']) .kpis {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }
    }
    @media (max-width: 599px) {
      :host([data-tile-layout='compact']) .kpis {
        grid-template-columns: repeat(var(--lv-tile-compact-cols-phone), minmax(0, 1fr));
      }
    }
    /* R5-LIVE-297 (the HOMEFABLE method on the live overview, structure unchanged): three surface tiers - the four counters are the
       hero (a 32 px / 800 display numeral through the sw-kpi value hook), the cards the second tier, every row inside a card a WELL
       (surface-2, rounded, no hairline); a state is a filled field (the tone's tint behind a dot and a bold word), not a dot on white;
       the critical attention item is a filled danger field; rows sink on pointer-down and tint on hover only under a fine pointer */
    .kpis {
      --sw-kpi-value-fs: var(--sw-fs-4xl);
      --sw-kpi-value-fw: 800;
    }
    .donut svg {
      inline-size: 96px;
      block-size: 96px;
    }
    .donut .big {
      font-size: var(--sw-fs-2xl);
      font-weight: 800;
      letter-spacing: -0.02em;
      color: var(--sw-heading);
      font-variant-numeric: tabular-nums;
    }
    .bar {
      block-size: 10px;
      border-radius: var(--sw-r-pill);
      margin-block: 8px 6px;
    }
    .bar i {
      border-radius: var(--sw-r-pill);
    }
    .hrow,
    .ev,
    .spot {
      border-block-end: 0;
      margin-inline: 0;
      margin-block-end: 5px;
      padding: 7px 12px; /* loop 1: 9 px left two events in view at 1440 x 900 */
      border-radius: var(--sw-r-md);
      background: var(--sw-surface-2);
      -webkit-tap-highlight-color: transparent;
      touch-action: manipulation;
    }
    .hrow:last-child,
    .ev:last-child,
    .spot:last-child {
      margin-block-end: 0;
    }
    /* NOSCROLL-1366-2437: the health rows sit in a grid; on a short desktop (1366x768 class) they take two columns, so the row of
       health / storage gives the last row (events, attention) the room it needs and the page does not scroll. From 1280 px only:
       at 1024x768 the half-width cells and the lower floor squeezed the attention card below one item (entry check 2026-11-12) */
    .hgrid {
      display: grid;
      gap: 5px;
    }
    .hgrid > .hrow {
      margin-block-end: 0;
    }
    @media (min-width: 1280px) and (max-height: 860px) {
      .hgrid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
      .row3 {
        min-block-size: 160px;
      }
    }
    .hrow > span:first-child,
    .spot .t,
    .ev .txt b {
      font-size: var(--sw-fs-md);
      font-weight: var(--sw-fw-semibold);
      color: var(--sw-heading);
    }
    .ev time {
      font-size: var(--sw-fs-sm);
      font-weight: var(--sw-fw-semibold);
      color: var(--sw-text-2);
      font-variant-numeric: tabular-nums;
    }
    .ev sw-scene,
    .ev img.thumb,
    .ev .none {
      inline-size: 64px;
      block-size: 40px;
      border-radius: var(--sw-r-sm);
    }
    .status {
      position: relative;
      isolation: isolate;
      flex: none;
      min-block-size: 26px;
      padding: 0 11px;
      gap: 7px;
      font-size: var(--sw-fs-sm);
      font-weight: var(--sw-fw-bold);
      color: var(--sw-heading);
    }
    .status i::after {
      content: '';
      position: absolute;
      inset: 0;
      z-index: -1;
      border-radius: var(--sw-r-pill);
      background: color-mix(in srgb, var(--c) 20%, var(--sw-surface));
    }
    .spot {
      align-items: center;
    }
    .spot .ic {
      inline-size: 36px;
      block-size: 36px;
      border-radius: 50%;
    }
    .spot.critical {
      background: var(--sw-danger-soft);
    }
    .spot.critical .ic {
      background: var(--sw-danger);
      color: var(--sw-text-inverse);
    }
    .spot .why {
      color: var(--sw-text-2);
    }
    .seeall {
      font-size: var(--sw-fs-sm);
      font-weight: var(--sw-fw-semibold);
    }
    .hrow.link,
    .ev {
      transition: background-color var(--sw-t-fast) var(--sw-ease), transform var(--sw-t-press) var(--sw-ease-out);
    }
    @media (hover: hover) and (pointer: fine) {
      .hrow.link:hover,
      .ev:hover {
        background: var(--sw-surface-3);
      }
    }
    .hrow.link:active,
    .ev:active {
      transform: scale(var(--sw-press-scale, 0.98));
      background: var(--sw-pressed-wash);
    }
    @media (prefers-reduced-motion: reduce) {
      .hrow.link:active,
      .ev:active {
        transform: none;
      }
    }
  `];


  /** WARMUP-POLISH-2421: the attention card. On a desktop (>= 1024 px, where the page fits the viewport) the items that do not fit
   * the card's height are paged ("1-2 מתוך 3" with previous / next) instead of scrolling inside the card; below that the page scrolls
   * as before and every item is shown. */
  private renderAttention(spots: Spot[], calm: unknown) {
    if (spots.length !== this.spotCount) {
      this.spotCount = spots.length;
      this.spotMeasure = true;
    }
    const fit = this.spotFit !== null && this.spotFit < spots.length ? this.spotFit : null;
    const pages = fit ? Math.ceil(spots.length / fit) : 1;
    const page = Math.min(this.spotPage, pages - 1);
    const shown = fit ? spots.slice(page * fit, page * fit + fit) : spots;
    return html`<sw-card fill clip data-overview-attention heading="דורש תשומת לב" subheading="כל פריט מסביר מדוע הוא מוצג">
      ${spots.length
        ? shown.map(
            (s) => html`<div class="spot ${s.kind}" data-overview-spot>
              <div class="ic"><sw-icon name=${s.kind === 'critical' ? 'offline' : s.kind === 'info' ? 'info' : 'warning'} size=${15}></sw-icon></div>
              <div class="sbody"><div class="t" title=${s.title}>${s.title}</div><div class="muted" title=${s.meta}>${s.meta}</div><div class="why" title=${s.why}>${s.why}</div></div>
              <div class="actions"><a href=${s.link}><sw-button size="sm">פתח</sw-button></a></div>
            </div>`,
          )
        : calm}
      ${fit
        ? html`<div class="spotpager" data-overview-spot-pager>
            <button type="button" data-spot-prev aria-label="הפריטים הקודמים" ?disabled=${page === 0} @click=${() => (this.spotPage = page - 1)}><sw-icon name="chevron" size=${14}></sw-icon></button>
            <span data-overview-spot-range>${fit === 1 ? String(page + 1) : bidi(`${page * fit + 1}–${Math.min(spots.length, page * fit + fit)}`)} מתוך ${spots.length}</span>
            <button type="button" data-spot-next aria-label="הפריטים הבאים" ?disabled=${page >= pages - 1} @click=${() => (this.spotPage = page + 1)}><sw-icon name="chevronBack" size=${14}></sw-icon></button>
          </div>`
        : nothing}
    </sw-card>`;
  }

  protected updated() {
    const card = this.renderRoot.querySelector<HTMLElement>('sw-card[data-overview-attention]');
    if (!card) return;
    const pageEl = this.renderRoot.querySelector<HTMLElement>('sw-page');
    if (!this.spotObserver && pageEl && typeof ResizeObserver !== 'undefined') {
      // the page's box follows the viewport on a desktop (block-size: 100%), not what the card shows - no measure loop
      this.spotObserver = new ResizeObserver(() => {
        this.spotMeasure = true;
        this.requestUpdate();
      });
      this.spotObserver.observe(pageEl);
    }
    if (!this.spotMeasure) return;
    if (this.spotFit !== null) {
      this.spotFit = null; // a new measure starts from every item rendered (the next update measures)
      return;
    }
    requestAnimationFrame(() => this.measureSpots());
  }

  /** WARMUP-POLISH-2421: count the attention items that fit (every item rendered, after layout). */
  private measureSpots() {
    if (!this.spotMeasure || this.spotFit !== null) return;
    this.spotMeasure = false;
    const card = this.renderRoot.querySelector<HTMLElement>('sw-card[data-overview-attention]');
    const desktop = typeof matchMedia === 'function' && matchMedia('(min-width: 1024px)').matches;
    const body = card?.shadowRoot?.querySelector<HTMLElement>('.body');
    const items = card ? [...card.querySelectorAll<HTMLElement>('[data-overview-spot]')] : [];
    if (!desktop || !body || !items.length) return;
    const pad = parseFloat(getComputedStyle(body).paddingBottom || '0') || 0;
    const fit = attentionFit(body.getBoundingClientRect().top + body.clientHeight - pad, items.map((el) => el.getBoundingClientRect().bottom));
    if (fit < items.length) this.spotFit = fit;
  }


  render() {
    if (isApi()) return this.renderApi();
    const online = demoWall.filter((c) => c.state === 'live' || c.state === 'stale').length;
    const unacked = demoEvents.filter((e) => !e.acked);
    const spotlights = [
      { kind: 'critical', title: 'מצלמה מנותקת: מסדרון מזרחי', meta: 'קומה 0 · מאז 07:55', why: 'מוצג כי אין הקלטה ממצלמה זו כבר שעתיים', link: '#/system/devices' },
      { kind: 'alert', title: `${unacked.length} אירועים שלא נבדקו`, meta: 'אדם בכניסה הראשית 10:14, רכב בחצר 09:42', why: 'מוצג כי אירועי אדם/רכב מחכים לסימון טיפול', link: '#/investigate/events' },
      { kind: 'alert', title: 'החיבור לתשתית המערכת לא רענן', meta: 'סנכרון אחרון לפני 4 דק׳', why: 'מוצג כי מצבי הישויות עלולים להיות מיושנים', link: '#/system/diagnostics' },
    ];
    const used = 0.68;
    const r = 34;
    const c = 2 * Math.PI * r;
    const favorites = demoWall.filter((x) => x.state === 'live').slice(0, 2);
    const layout = this.tiles.layout;
    return html`
      <sw-page heading="בוקר טוב, יוני" subheading="המערכת פועלת · גשר לא רענן · נתוני הדגמה">
        <div slot="actions" class="date">יום שני, 14 בספטמבר 2026<br />10:24</div>
        <div class="kpis" data-overview-kpis>
          <sw-kpi data-overview-tile="cameras" icon="camera" tone="live" value=${String(online)} label="מצלמות" detail="מחוברות" layout=${layout} href="#/system/devices?sort=offline" hint="פתח את רשימת המצלמות"></sw-kpi>
          <sw-kpi data-overview-tile="sites" icon="building" value=${String(demoSites.length)} label="אתרים" detail="פעילים" tone="neutral" layout=${layout} href="#/explore/sites" hint="פתח את האתרים"></sw-kpi>
          <sw-kpi data-overview-tile="events" icon="bell" value=${String(demoEvents.length)} label="אירועים" detail="ב־24 השעות" tone="neutral" badge=${`${unacked.length} חדשים`} layout=${layout} href="#/investigate/events" hint="פתח את האירועים"></sw-kpi>
          <sw-kpi data-overview-tile="health" icon="shield" tone="stale" value="חלקי" label="מצב מערכת" detail="גשר לא רענן" layout=${layout} href="#/system/diagnostics?tab=health" hint="פתח את פרטי הבריאות"></sw-kpi>
        </div>
        <div class="fav">
          ${favorites.map((cam) => html`<sw-camera-tile name=${cam.name} state=${cam.state} scene=${demoScene[cam.id] ?? 'lobby'} @click=${() => navigate(`/live/cameras/${cam.id}`)}></sw-camera-tile>`)}
        </div>
        <div class="row2">
          <sw-card heading="אחסון">
            <div class="donut">
              <svg viewBox="0 0 84 84" role="img" aria-label="אחסון בשימוש 68%">
                ${svg`<circle cx="42" cy="42" r=${r} fill="none" stroke="var(--sw-surface-3)" stroke-width="9" />
                <circle cx="42" cy="42" r=${r} fill="none" stroke="var(--sw-accent)" stroke-width="9" stroke-linecap="round" stroke-dasharray=${`${c * used} ${c}`} transform="rotate(-90 42 42)" />
                <text x="42" y="47" text-anchor="middle" font-size="15" font-weight="700" fill="var(--sw-text)" font-family="var(--sw-font)">68%</text>`}
              </svg>
              <div class="txt">
                <div class="big">${bidi('1.3 TB מתוך 1.9 TB')}</div>
                <div class="bar"><i></i></div>
                <div class="muted">הקלטה ישנה ביותר ≈ 11 ימים (נמדד) · overwrite פעיל</div>
              </div>
            </div>
          </sw-card>
          <sw-card heading="בריאות האתרים">
            <div class="hgrid">${demoSites.map((s) => html`<div class="hrow"><span>${s.name}<div class="muted">${s.online}/${s.cameras} מצלמות · ${s.alerts} התראות</div></span><span class="status"><i style="--c:${s.health === 'live' ? 'var(--sw-live)' : s.health === 'offline' ? 'var(--sw-danger)' : 'var(--sw-stale)'}"></i>${s.health === 'live' ? 'מחובר' : s.health === 'offline' ? 'מנותק' : 'חלקי'}</span></div>`)}
            ${demoHealth.slice(0, 2).map((h) => html`<div class="hrow"><span>${h.name}<div class="muted">${h.detail}</div></span><span class="status"><i style="--c:${h.state === 'live' ? 'var(--sw-live)' : 'var(--sw-stale)'}"></i>${h.state === 'live' ? 'מחובר' : 'לא רענן'}</span></div>`)}</div>
          </sw-card>
        </div>
        <div class="row3">
          <sw-card fill heading="אירועים אחרונים">
            <a slot="actions" class="seeall" href="#/investigate/events">הצג הכל</a>
            ${demoEvents.slice(0, 5).map(
              (e) => html`<div class="ev" role="link" tabindex="0" @click=${() => navigate('/investigate/events')} @keydown=${(k: KeyboardEvent) => { if (k.key === 'Enter' || k.key === ' ') { k.preventDefault(); navigate('/investigate/events'); } }}>
                ${e.type === 'offline' || e.type === 'door'
                  ? html`<div class="none"><sw-icon name=${e.type === 'offline' ? 'offline' : 'door'} size=${14}></sw-icon></div>`
                  : html`<sw-scene kind=${(EVENT_SCENE[e.camera] ?? 'lobby') as 'lobby'}></sw-scene>`}
                <div class="txt"><b style="--tone:${EVENT_TONE[e.type]}"><i></i>${eventTypeLabel[e.type]}</b><small>${e.camera} · ${e.floor}</small></div>
                <time>${e.time}</time>
              </div>`,
            )}
          </sw-card>
          ${this.renderAttention(spotlights as Spot[], nothing)}
        </div>
      </sw-page>
    `;
  }
}
